function timeMinutes(value){if(!/^\d{2}:\d{2}$/.test(value))throw Error('Choose a valid wake time.');const [h,m]=value.split(':').map(Number);if(h>23||m>59)throw Error('Choose a valid wake time.');return h*60+m;}
