function probePayload(action){const payload={action};if(['feature-flags','config-values','reboot-probe'].includes(action)){if(!E('experimentalProbeConsent').checked)throw Error('Read and select the experimental probe acknowledgement first.');payload.experimental=true;}if(action==='config-values'){const text=E('probeKeys').value.trim();if(text){const keys=text.split(/\r?\n/).map(k=>k.trim()).filter(Boolean);if(keys.length>32||keys.some(k=>!/^[\x21-\x7e]{1,32}$/.test(k)))throw Error('Use at most 32 exact ASCII keys, each 1–32 characters without spaces.');payload.keys=keys;}}if(action==='reboot-probe'){payload.candidate=document.querySelector('[name="reboot_candidate"]').value;if(!rebootCandidates.slice(1).some(([id])=>id===payload.candidate))throw Error('Choose one exact unverified reboot candidate.');payload.confirm=true;}return payload;}
E('probePanel').addEventListener('click',async ev=>{const b=ev.target.closest('[data-probe]');if(!b)return;try{const payload=probePayload(b.dataset.probe);if(payload.action==='reboot-probe'&&!await boopConfirm({title:'Send unverified reboot candidate?',message:'Send '+payload.candidate+' exactly once? This unverified strap candidate may drop the recording connection. Normal restart is unsupported.',confirmLabel:'Send selected candidate',destructive:true,trigger:b}))return;b.disabled=true;E('probeResult').textContent='Probe requested · waiting for the strap response…';const result=await api('/api/device',payload);E('probeResult').textContent=result.message||'Probe request recorded. Review the reported state below.';E('probeStatus').innerHTML=summary(result.probe||result);}catch(e){E('probeResult').textContent=e.message;fail(e);}finally{b.disabled=false;}});

