function applyTodayLayout(){const order=localLayout.todayOrder||todayGroups.flatMap(([,items])=>items.map(([key])=>key));for(const group of [document.querySelector('#dailyCards .metric-grid'),document.querySelector('#today .metrics')])if(group){const cards=[...group.children];for(const card of cards){const key=card.dataset.metric;card.hidden=localLayout['show_'+key]===false;if(latestToday&&['charge','effort','rest'].includes(key)){const value=latestToday[key]?.value;card.classList.toggle('has-observed-score',typeof value==='number');card.style.setProperty('--score-level',(typeof value==='number'?Math.max(0,Math.min(100,value)):0)+'%');}}cards.sort((a,b)=>order.indexOf(a.dataset.metric)-order.indexOf(b.dataset.metric)).forEach(card=>group.append(card));}document.body.dataset.todayStyle=localLayout.todayStyle||(localLayout.compact?'compact':'classic');for(const group of document.querySelectorAll('.today-order-list')){[...group.children].sort((a,b)=>order.indexOf(a.dataset.layoutKey)-order.indexOf(b.dataset.layoutKey)).forEach(row=>group.append(row));const rows=[...group.children];rows.forEach((row,i)=>{row.querySelector('[data-card-move="up"]').disabled=i===0;row.querySelector('[data-card-move="down"]').disabled=i===rows.length-1;});}}
E('layoutForm').addEventListener('click',ev=>{const b=ev.target.closest('[data-card-move]');if(!b)return;const row=b.closest('.today-order-row');if(b.dataset.cardMove==='up'&&row.previousElementSibling)row.previousElementSibling.before(row);if(b.dataset.cardMove==='down'&&row.nextElementSibling)row.nextElementSibling.after(row);localLayout.todayOrder=[...document.querySelectorAll('[data-layout-key]')].map(row=>row.dataset.layoutKey);applyTodayLayout();});
function coupledReadout(v){return '<div class="three-contexts">'+[['charge','Recovery against your personal baseline','Nightly HRV, resting HR and other covered nighttime signals provide context.'],['effort','Your recorded cardiovascular effort','Observed HR-zone duration describes the day’s cardiovascular work.'],['rest','Your observed sleep restoration','Recorded sleep duration, efficiency and restorative stages provide sleep context.']].map(([key,title,copy])=>`<section><p class="eyebrow">${label(key)}</p><h3>${title}</h3>${help(v[key]?.value!=null?copy:esc(v[key]?.reason||'More covered observations are needed.'))}<details><summary>Observed contributors & coverage</summary>${summary({inputs:v[key]?.inputs||v[key]?.components||v[key]?.contributors,coverage:v[key]?.coverage,hrv:key==='charge'?v.hrv:undefined,resting_hr:key==='charge'?v.resting_hr:undefined,sleep:key==='rest'?v.sleep?.main:undefined,zones:key==='effort'?v.effort?.zone_minutes:undefined})}</details></section>`).join('')+'</div>'+help('These describe different parts of the same observed day. Missing signals remain missing; no score is a recommendation.');}
function activityHeatmap(rows){if(!rows?.length)return help('No calendar observations in the selected range.');return `<div class="activity-heatmap" role="group" aria-label="Observed activity days">${rows.slice(-90).map(r=>`<button type="button" data-day="${esc(r.day)}" class="${r.workouts?'worked':r.observed?'covered':'unobserved'}" aria-label="${esc(r.day)}: ${r.workouts||0} workouts, ${r.observed?'measured outcomes':'no measured outcomes'}${r.journal?', journal logged':''}" title="${esc(r.day)} · ${r.workouts||0} workouts${r.journal?' · journal logged':''}"><span>${r.day.slice(-2)}</span>${r.journal?'<i aria-hidden="true">•</i>':''}</button>`).join('')}</div><p class="chart-legend">Open any day · filled = workout · pale = measured outcome · dot = journal</p>`;}

