function installLabCatalog(list){if(!Array.isArray(list)||!list.length)return;labCatalog=list;const select=labForm.elements.marker,value=select.value;select.innerHTML='<option value="">Choose a marker</option>'+list.map(m=>`<option value="${esc(m.key)}">${esc(m.display_name)}${m.canonical_unit?' · '+esc(m.canonical_unit):''}</option>`).join('')+'<option value="__custom">Other marker · enter exact name</option>';select.value=value;}
