function vitalBandReadout(bands){if(!bands)return help('Vital comparisons are awaiting observed readings.');const names={respiration:'Breathing rate',spo2:'Blood oxygen',resting_hr:'Resting HR',hrv:'Nightly HRV',skin_temperature:'Skin temperature'},units={respiration:'breaths/min',spo2:'%',resting_hr:'bpm',hrv:'ms',skin_temperature:preferences.temperature_units==='fahrenheit'||(!preferences.temperature_units&&imperial())?'°F':'°C'};return `<details class="vital-band-panel"><summary>Personal context & reference bands</summary><div class="vital-context">${Object.entries(bands).map(([key,b])=>`<p><strong>${names[key]||label(key)}</strong><span>${b.value==null?'No observed value':human(displayedMetric(key,b.value))+' '+(units[key]||'')+' · '+(b.band==='inRange'?'Within comparison band':b.band==='outOfRange'?'Outside comparison band':'No comparison available')}<small>${b.basis==='personal'?'Your personal baseline · '+(b.nights||0)+' usable nights':'Population reference · personal baseline needs 14 usable nights'}</small></span></p>`).join('')}</div>${help('Bands describe a comparison, not a diagnosis. Population references are shown separately from personal baselines.')}<details><summary>Ranges, coverage & source evidence</summary>${summary(bands)}</details></details>`;}
function poincareChart(points){points=(points||[]).filter(p=>Number.isFinite(p.x)&&Number.isFinite(p.y));if(!points.length)return help('No eligible consecutive RR pairs to plot.');const values=points.flatMap(p=>[p.x,p.y]),lo=Math.floor(Math.min(...values)/50)*50,hi=Math.ceil(Math.max(...values)/50)*50,span=hi-lo||50,plot=points.slice(-400);return `<svg class="mini-chart poincare-chart" viewBox="0 0 440 290" role="img" tabindex="0" aria-label="Consecutive RR intervals: ${points.length} observed pairs, milliseconds"><path d="M50 20V240H420" stroke="currentColor" fill="none" opacity=".35"/><path d="M50 240L420 20" stroke="currentColor" opacity=".15" stroke-dasharray="4 5"/>${plot.map(p=>`<circle cx="${50+(p.x-lo)/span*370}" cy="${240-(p.y-lo)/span*220}" r="2.2" fill="currentColor" opacity=".55"/>`).join('')}<text x="50" y="265">${lo} ms</text><text x="420" y="265" text-anchor="end">${hi} ms</text><text x="50" y="285">RR interval → next RR interval</text></svg><p class="chart-legend">Latest ${plot.length} of ${points.length} consecutive pairs · milliseconds</p>`;}
function rhythmReadout(r){if(!r)return help('Rhythm observations are awaiting a covered stillness window.');const names={steady:'Steady interval pattern',occasionalEctopy:'Occasional interval variation',varied:'Varied interval pattern',unreadable:'Not enough reliable interval coverage'},empty={none:'No eligible nighttime RR windows yet.',gatheringData:'More correctly timed RR beats and stillness coverage are needed.',deviceBanksBeats:'This source banks RR beats without reliable individual timing. A rhythm pattern cannot be inferred from them.',deviceNoMotion:'Stillness coverage is unavailable for this source; rhythm windows remain unreadable.'},windows=(r.windows||[]).filter(w=>w.label!=='unreadable');return `<div class="insight-outcome"><h3>${names[r.night?.overall]||'Observed beat-to-beat patterns'}</h3>${windows.length?help(windows.length+' readable nighttime windows · '+(r.night?.steady_windows||0)+' steady · '+(r.night?.occasional_windows||0)+' occasional variation · '+(r.night?.varied_windows||0)+' varied'):help(empty[r.empty_state]||'No trustworthy consecutive-beat window is available for this date.')}${help('Patterns describe recorded intervals only. They do not establish an arrhythmia or medical condition.')}${windows.slice(-6).map(w=>`<details class="rhythm-window"><summary>${esc(names[w.label]||'Observed pattern')} · ${esc(recordTime(w.start))} · ${w.n_beats} beats</summary>${poincareChart(w.poincare)}<details><summary>Window coverage & source evidence</summary>${summary(w)}</details></details>`).join('')}<details><summary>Night coverage & method evidence</summary>${summary(r)}</details></div>`;}
function labBookReadout(book){const markers=book?.markers||[];if(!markers.length)return help('Your first saved or imported numeric lab reading will start a marker history. Reference ranges come from your own report.');return markers.map(m=>`<details class="lab-marker"><summary><span>${esc(m.label)}</span><strong>${m.latest?human(m.latest.value)+' '+esc(m.unit||''):'No numeric reading'}</strong></summary>${help(m.latest?'Latest reading · '+esc(m.latest.day||m.latest.date||''): 'Awaiting a dated numeric reading.')}${chart((m.history||[]).map(p=>({x:p.day||p.date,y:p.value})),m.label+' · '+(m.unit||''))}<details><summary>Compare paired wearable observations</summary>${Object.entries(m.associations||{}).map(([key,a])=>`<section class="insight-section"><h3>${esc(label(key))}</h3>${help((a.pairs?.length||0)+' paired lab dates · '+a.window_days+'-day trailing wearable mean')}${a.correlation?.value!=null?help('Observed correlation r '+human(a.correlation.value)):help(a.correlation?.reason||'More paired observations and variation are needed.')}<details><summary>Exact pairs & coverage</summary>${summary(a)}</details></section>`).join('')}${help('Paired measurements are associations. Lab values and wearable means retain separate units and timing.')}</details>${m.report_references?.length?'<details><summary>Reference ranges from your report</summary>'+summary(m.report_references)+'</details>':''}<details><summary>Marker history & source evidence</summary>${summary(m)}</details></details>`).join('');}
function renderHealthProjections(p){E('vitalBands').innerHTML=vitalBandReadout(p?.vital_bands);E('rhythmProjection').innerHTML=rhythmReadout(p?.rhythm);E('labProjection').innerHTML=labBookReadout(p?.lab_book);if(!labCatalog.length)installLabCatalog(p?.marker_catalog);}
