function backupConfig(v,options){const directory=String(v.directory||'').trim(),keep=Number(v.keep_count);if(!directory)throw Error('Enter a local backup folder, or retain the default folder.');if(!options.includes(keep))throw Error('Choose a supported saved-copy count.');return {enabled:!!v.enabled,directory,keep_count:keep};}
function renderBackupSchedule(v){const f=E('backupScheduleForm'),state=v.state||{};backupKeepOptions=v.keep_options||[1,3,5,7,10,14];f.elements.enabled.checked=!!v.enabled;f.elements.directory.value=v.directory||'';f.elements.keep_count.innerHTML=backupKeepOptions.map(n=>`<option value="${n}">${n} ${n===1?'copy':'copies'}</option>`).join('');f.elements.keep_count.value=v.keep_count??7;E('backupScheduleState').innerHTML=help(v.enabled?'Daily local copies are enabled while BOOP is running.':'Daily local copies are off. You can still create a copy now.')+(state.last_error?help('Last attempt: '+esc(state.last_error)):'')+'<details><summary>Last backup & schedule details</summary>'+summary({running_required:v.running_required,note:v.note,state})+'</details>';E('scheduledBackupFiles').innerHTML=(v.files||[]).length?'<ul class="diagnostic-files">'+v.files.map(file=>`<li><div><strong>${esc(file.name)}</strong><span>${human(file.size_bytes/1024)} KB · ${esc(new Date(file.modified_ms).toLocaleString('en-AU'))}</span></div><div class="buttons"><a class="button" href="/api/backups/export?file=${encodeURIComponent(file.name)}">Download copy</a><button type="button" data-backup-restore="${esc(file.name)}">Restore this copy</button></div></li>`).join('')+'</ul>':help('No scheduled copies are saved yet. Create a backup now or enable daily copies.');}
