function renderDiagnosticSchedule(v){const f=E('diagnosticScheduleForm');diagnosticKeepOptions=v.keep_options||[3,7,14,30,60];f.elements.enabled.checked=!!v.enabled;f.elements.diagnostic_time.value=minuteTime(v.time_minutes??420);f.elements.keep_count.innerHTML=diagnosticKeepOptions.map(n=>`<option value="${n}">${n} exports</option>`).join('');f.elements.keep_count.value=v.keep_count??14;const state=v.state||{};E('diagnosticScheduleState').innerHTML=help(esc((v.enabled?'Scheduled while BOOP is running.':'Scheduled exports are off.')+(state.last_success_at?' Last completed: '+new Date(state.last_success_at).toLocaleString('en-AU')+'.':'')))+(state.last_error?help('Last attempt: '+esc(state.last_error)):'')+'<details><summary>Storage & last-run details</summary>'+summary({directory:v.directory,last_file:state.last_file,last_run_day:state.last_run_day,running_required:v.running_required})+'</details>';E('diagnosticFiles').innerHTML=(v.files||[]).length?'<ul class="diagnostic-files">'+v.files.map(file=>`<li><a href="/api/diagnostics/export?file=${encodeURIComponent(file.name)}">${esc(file.name)}</a><span>${human(file.size_bytes/1024)} KB · ${esc(new Date(file.modified_ms).toLocaleString('en-AU'))}</span></li>`).join('')+'</ul>':help('No saved diagnostic ZIPs yet. Create one now or enable the schedule.');}
