function coachLocalEndpoint(provider,endpoint){if(['offline','ollama'].includes(provider))return true;if(provider!=='compatible')return false;try{const url=new URL(endpoint),host=url.hostname.toLowerCase().replace(/^\[|\]$/g,'');return ['http:','https:'].includes(url.protocol)&&['localhost','127.0.0.1','::1'].includes(host);}catch{return false;}}
function coachRequestOptions(v){if(v.provider!=='compatible'){delete v.auth_header;delete v.auth_prefix;delete v.system_prompt;return v;}v.auth_header=v.auth_header||'Authorization';if(!/^[!#$%&'*+.^_`|~0-9A-Za-z-]{1,64}$/.test(v.auth_header))throw Error('Use a valid authentication header name, up to 64 characters.');if(v.auth_prefix.length>128||/[^\x20-\x7e]/.test(v.auth_prefix))throw Error('Authentication prefix must contain at most 128 printable characters.');if(v.system_prompt.length>4000)throw Error('Keep supplemental preferences within 4,000 characters.');const url=new URL(v.endpoint);if(!coachLocalEndpoint(v.provider,v.endpoint)){if(url.protocol!=='https:')throw Error('External compatible endpoints require HTTPS.');if(!v.api_key)throw Error('Enter a key for this external compatible request.');}return v;}
