function coachModelRequest(v){const local=coachLocalEndpoint(v.provider,v.endpoint);if(!local){if(!v.consent)throw Error('Check external-provider consent before refreshing models.');if(!v.api_key)throw Error('Enter a request-only key to refresh this external provider.');}if(v.provider==='compatible')coachRequestOptions({...v,system_prompt:''});const request={provider:v.provider,endpoint:v.endpoint||''};if(v.api_key)request.api_key=v.api_key;if(!local)request.consent=true;if(v.provider==='compatible'){request.auth_header=v.auth_header||'Authorization';request.auth_prefix=v.auth_prefix??'Bearer ';}return request;}
