E('refreshCoachModels').onclick=async()=>{if(coachModelsBusy||coachController)return;coachModelsBusy=true;const f=E('coachForm'),b=E('refreshCoachModels'),ask=f.querySelector('button:not([type="button"])');b.disabled=true;ask.disabled=true;E('coachModelsStatus').textContent='Reading available model names…';try{const v=await api('/api/coach/models',coachModelRequest(values(f))),count=renderCoachModelChoices(v.models);E('coachModelsStatus').textContent=count?count+' models available. Choose a suggestion or keep your typed model.':'This provider returned no model names. You can still enter a model ID.';}catch(error){E('coachModelsStatus').textContent=error.message;}finally{coachModelsBusy=false;b.disabled=!!coachController;ask.disabled=!coachMaster||!!coachController||coachModelsBusy;f.elements.api_key.value='';f.elements.consent.checked=false;}};
