function answerParagraphs(text){const paragraphs=String(text||'').trim().split(/\n\s*\n/).filter(Boolean);if(paragraphs.length!==1||paragraphs[0].length<500)return paragraphs;const sentences=paragraphs[0].split(/(?<=[.!?])\s+(?=[A-Z])/);if(sentences.length<3)return paragraphs;const size=Math.ceil(sentences.length/3);return Array.from({length:3},(_,i)=>sentences.slice(i*size,(i+1)*size).join(' ')).filter(Boolean);}
let coachController=null;
async function streamCoach(payload){const controller=new AbortController();coachController=controller;const reply=E('coachReply'),status=E('coachStreamStatus'),cancel=E('cancelCoach');let draft='',meta={provider:payload.provider};reply.innerHTML='<article class="coach-answer"><p class="eyebrow">REPLY IN PROGRESS · NOT SAVED</p><p class="coach-stream-draft"></p></article>';const draftNode=reply.querySelector('.coach-stream-draft');status.textContent='Preparing your reply from the recorded metric context…';reply.setAttribute('aria-busy','true');cancel.hidden=false;cancel.disabled=false;const controls=['clearCoach','undoCoachClear','generateBrief','refreshCoachModels'];controls.forEach(id=>{if(E(id))E(id).disabled=true;});try{const response=await boopCoachStream(payload,{signal:controller.signal,onEvent:event=>{if(event.type==='meta'){meta={...meta,...event};reply.querySelector('.eyebrow').textContent=(meta.local||['offline','ollama'].includes(meta.provider)?'GENERATING ON THIS LAPTOP':'GENERATING WITH YOUR SELECTED PROVIDER')+' · NOT SAVED';}if(event.type==='delta'){draft+=event.text||'';draftNode.textContent=draft;}}});if(controller.signal.aborted)throw new DOMException('The reply was cancelled.','AbortError');let result=response.result;if(response.fallback){const fallback=await fetch('/api/coach',{method:'POST',headers:{'Content-Type':'application/json','X-Boop':'local'},body:JSON.stringify(payload),signal:controller.signal});result=await fallback.json();if(!fallback.ok)throw Error(result.error||'The Coach could not finish this reply.');}reply.innerHTML=coachReadout(result);status.textContent='Reply complete.';try{await loadCoach(result);}catch(error){status.textContent='Reply complete. Saved history could not refresh: '+error.message;}}catch(error){const cancelled=error.name==='AbortError';reply.querySelector('.eyebrow').textContent=(cancelled?'CANCELLED':'INCOMPLETE')+' · UNSAVED DRAFT';draftNode.textContent=draft||(cancelled?'Reply cancelled before any text arrived.':'No reply text was received.');status.textContent=cancelled?'Reply cancelled. The partial draft has not been saved.':error.message+' The partial draft has not been saved.';}finally{reply.removeAttribute('aria-busy');cancel.hidden=true;coachController=null;controls.forEach(id=>{if(E(id))E(id).disabled=id==='generateBrief'?!coachMaster:false;});E('coachForm').elements.api_key.value='';E('coachForm').elements.consent.checked=false;}}
E('cancelCoach').onclick=()=>{E('cancelCoach').disabled=true;coachController?.abort();};
let coachLiveMetadata=null;
function coachReadout(v){const text=v.answer||v.text||'',archived=!!v.archived,saved=archived||v.saved===true,local=v.local===true||['offline','ollama'].includes(v.provider),eyebrow=local?'GENERATED ON THIS LAPTOP':archived?'SAVED COACH REPLY':v.local===false?'ANSWER FROM YOUR SELECTED EXTERNAL PROVIDER':'COACH REPLY',model=v.model?esc(v.model):archived?'Historic model not recorded.':'Model not recorded.',context=v.data_sent!=null?(typeof v.data_sent==='string'?esc(v.data_sent):summary(v.data_sent)):archived?'Historic request context not recorded.':'Request context not recorded.';return `<article class="coach-answer"><p class="eyebrow">${eyebrow}</p>${answerParagraphs(text).map(p=>`<p>${esc(p)}</p>`).join('')}<details><summary>Provider, saved history & data context</summary><p><strong>Saved history:</strong> ${saved?'Saved locally in your conversation.':v.saved===false?'This reply has not been saved.':'Save status not recorded.'}</p><p><strong>Provider:</strong> ${v.provider?esc(v.provider):'Provider not recorded.'}</p><p><strong>Model:</strong> ${model}</p><p><strong>Request context:</strong> ${context}</p></details></article>`;}

function coachHistoryReadout(v){const messages=v.messages||[];if(!messages.length)return help('Your local conversation is empty. Completed questions and answers are saved on this laptop.');let date='';const previous=messages.slice(0,-1);return `<details class="coach-history"><summary>Local conversation · ${messages.length} messages</summary>${previous.map(m=>{const day=new Date(m.created_ms).toLocaleDateString('en-AU'),separator=day!==date?`<p class="conversation-date">${esc(day)}</p>`:'';date=day;return separator+`<article class="conversation-message ${m.role==='user'?'question':'answer'}"><p class="eyebrow">${m.role==='user'?'YOUR QUESTION':'COACH'}</p>${answerParagraphs(m.text).map(p=>`<p>${esc(p)}</p>`).join('')}</article>`;}).join('')}</details>`;}
function populateCoachBrief(v){const f=E('coachBriefForm');coachMaster=v.master_enabled!==false;f.elements.master_enabled.checked=coachMaster;f.elements.enabled.checked=!!v.enabled;f.elements.brief_time.value=minuteTime(v.time_minutes??420);E('generateBrief').disabled=!coachMaster;E('coachForm').querySelector('button:not([type="button"])').disabled=!coachMaster||!!coachController||coachModelsBusy;E('coachBriefResult').innerHTML=v.last_text?coachReadout({text:v.last_text,provider:'offline',local:true}) :help(coachMaster?'No daily brief has been generated yet.':'The Coach is off. Its preferences and saved conversation remain accessible.');}
async function loadCoach(freshResult){const [options,history,brief]=await Promise.all([api('/api/coach/options'),api('/api/coach/history'),api('/api/coach/brief')]);populateCoachBrief(brief);E('coachOptions').innerHTML='<details><summary>Available providers & local model configuration</summary>'+summary(options)+'</details>'+help('Local explanations are the default. Choose a provider and model above to use your own configured service.');E('coachTranscript').innerHTML=coachHistoryReadout(history);E('undoCoachClear').hidden=!history.undo_available;const last=[...(history.messages||[])].reverse().find(m=>m.role==='assistant');if(last){if(freshResult&&(freshResult.answer||freshResult.text)===last.text)coachLiveMetadata={id:last.id,provider:freshResult.provider??last.provider,model:freshResult.model,local:freshResult.local,data_sent:freshResult.data_sent};const live=coachLiveMetadata?.id===last.id?coachLiveMetadata:null;E('coachReply').innerHTML=coachReadout({...last,...(live||{}),archived:!live,saved:true});}else{coachLiveMetadata=null;E('coachReply').replaceChildren();}}
E('undoCoachClear').onclick=async()=>{const b=E('undoCoachClear');b.disabled=true;try{await api('/api/coach/history',{action:'undo'});await loadCoach();notice('Local conversation restored.');}catch(e){fail(e);}finally{b.disabled=false;}};
E('generateBrief').onclick=async()=>{const b=E('generateBrief');b.disabled=true;E('coachBriefResult').textContent='The local model is preparing your brief…';try{const v=await api('/api/coach/brief',{action:'generate'});populateCoachBrief(v.brief||v);await loadCoach();}catch(e){E('coachBriefResult').textContent=e.message;fail(e);}finally{b.disabled=!coachMaster;}};

