function preSleepReadout(f){f=f?.value??f;const reasons={disabled:'Off by default. Enable pre-sleep observations in Settings to review the following morning.',invalidDay:'Choose a valid day to review an observation.',invalidWindow:'The recorded observation window is invalid.',missingPrimarySleep:'An observed primary sleep session is needed to locate the preceding window.',insufficientPreSleepSamples:'Not enough valid HR readings in the 30 minutes before sleep.',insufficientBaseline:'More eligible previous nights are needed for a personal comparison.',staleBaseline:'Your previous baseline is too old for a current comparison.'};const o=f?.observation,c=f?.comparison;return `<div class="morning-observation"><p class="eyebrow">THE 30 MINUTES BEFORE YOUR LONGEST SLEEP</p>${o?`<strong>${human(o.mean_bpm)} <small>bpm observed</small></strong><p>${o.valid_samples} valid samples${c?' · '+(c.delta_bpm>0?'+':'')+human(c.delta_bpm)+' bpm vs '+c.baseline_nights+' previous nights':''}</p>`:''}${help(esc(f?.eligibility==='eligible'?'A descriptive personal comparison of recorded HR before sleep.':reasons[f?.eligibility]||'Awaiting a covered sleep and preceding HR window.'))}${help('This is a retrospective morning observation. It does not recommend an action or attribute one night to a habit.')}<details><summary>Window, baseline & measurement coverage</summary>${summary(f)}</details></div>`;}
function liftingReadout(l){const wrapped=l?.sessions||{},sessions=Array.isArray(wrapped)?wrapped:wrapped.value||[],unit=imperial()?'lb':'kg',weight=v=>v==null?'—':human(userValue('weight_kg',v))+' '+unit;if(!sessions.length)return help(esc(wrapped.reason||'Link recorded sets to a workout for session history. A comparison needs an earlier session with the same exercise and known order.'));return sessions.map(session=>`<details class="lift-comparison" open><summary>${esc(session.day||'Recorded session')} · ${session.exercises?.length||0} ${(session.exercises?.length||0)===1?'exercise':'exercises'}</summary><div class="table-scroll"><table><caption>Working-set volume compared with the previous observed session</caption><thead><tr><th scope="col">Exercise</th><th scope="col">Working sets</th><th scope="col">Volume</th><th scope="col">Previous volume</th><th scope="col">Change</th></tr></thead><tbody>${(session.exercises||[]).map(x=>`<tr><th scope="row">${esc(x.exercise)}</th><td>${human(x.working_sets)}</td><td>${weight(x.volume_kg)}</td><td>${weight(x.previous_volume_kg)}</td><td>${x.volume_delta_kg==null?'Needs an earlier paired session':(x.volume_delta_kg>0?'+':'')+weight(x.volume_delta_kg)}</td></tr>`).join('')}</tbody></table></div></details>`).join('')+help('Volume is weight × repetitions for working sets. Compare the same exercise; this does not measure cardiovascular strain.')+`<details><summary>Session association & calculation evidence</summary>${summary(l)}</details>`;}
function sourceName(source){const names={noopComputed:'Local calculation',whoopImport:'Imported strap export',whoop:'Imported strap export',whoop_live_rr:'Live strap RR',appleHealth:'Apple Health',healthConnect:'Health Connect',xiaomiBand:'Xiaomi band',nutritionCsv:'Nutrition import',localCache:'Local cache',manual:'Manual entry'};return names[source]||(/\.swift\b/.test(String(source))?'Local calculation':label(String(source||'Unknown source').replace(/whoop/gi,'BOOP')));}
function fusionReadout(v){if(!v)return help('Source resolution is unavailable for this date.');const rows=[];if(v.winners){for(const[key,w]of Object.entries(v.winners)){rows.push({metric:key,value:w.value,source:w.winning_source||w.source,agreement:w.agreement||v.agreements?.[key],contributors:w.contributors||[]});}}else{for(const[key,w]of Object.entries(v.computed||{}))if(w.value!=null)rows.push({metric:key,value:w.value,source:w.source,agreement:'Local estimate · imported scores kept separate',contributors:[]});for(const[source,entries]of Object.entries(v.imported_sources||{}))for(const r of entries)for(const[key,value]of Object.entries(r))if(typeof value==='number'&&!['created_ms','updated_ms','timestamp_ms','start_ms','end_ms'].includes(key))rows.push({metric:key,value,source,agreement:'Imported observation · separate identity',contributors:[]});}return `${help(v.winners?'Chosen values retain their source. Agreement describes the contributing observations; values are never averaged.':'Computed estimates and imported official metrics retain separate identities.')}<div class="table-scroll"><table><caption>Source-attributed metrics · ${esc(v.day||v.date||day)}</caption><thead><tr><th scope="col">Metric</th><th scope="col">Value</th><th scope="col">Chosen source</th><th scope="col">Agreement & contributors</th></tr></thead><tbody>${rows.length?rows.map(r=>`<tr><th scope="row">${esc(label(r.metric))}</th><td>${esc(human(r.value))}</td><td>${esc(sourceName(r.source))}</td><td><span>${esc(label(r.agreement||'No paired sources'))}</span>${r.contributors.length?`<details><summary>${r.contributors.length} contributing observations</summary>${r.contributors.map(c=>`<p>${esc(sourceName(c.source_id||c.source))} · ${esc(human(c.value))}</p>`).join('')}</details>`:''}</td></tr>`).join(''):'<tr><td colspan="4">No sourced metric values for this date.</td></tr>'}</tbody></table></div><details><summary>Resolution policy & technical evidence</summary>${summary(v)}</details>`;}

