programForm.querySelector('.form-grid').insertAdjacentHTML('afterend','<section class="program-builder" aria-label="Ordered exercise targets"><div class="program-heading"><h3>Exercise targets</h3><button type="button" id="addProgramLine">＋ Add exercise</button></div><p class="subtle">Build your session in order. Targets are a plan; log completed sets in Lift Log.</p><div id="programLines"></div><p id="programEmpty" class="subtle">Add your first exercise to begin.</p></section>');
function programInput(key,title,value,type='text'){return `<label>${title}<input data-line-field="${key}" type="${type}" ${type==='number'?'min="0" step="any"':''} value="${esc(value??'')}"></label>`;}
function addProgramLine(line={}){const row=document.createElement('fieldset');row.className='program-line';row.originalLine={...line};const secondary=line.secondary_muscles??line.muscles??[];row.innerHTML=`<legend>Exercise</legend><div class="line-order"><span class="line-number"></span><div class="buttons"><button type="button" data-line-action="up" aria-label="Move exercise up">↑</button><button type="button" data-line-action="down" aria-label="Move exercise down">↓</button><button type="button" data-line-action="remove">Remove</button></div></div><div class="form-grid">${programInput('exercise','Exercise',line.exercise)}${programInput('target_sets','Sets',line.target_sets,'number')}${programInput('target_reps_low','Repetitions (minimum)',line.target_reps_low??line.target_reps,'number')}${programInput('target_weight_kg',imperial()?'Target weight (lb)':'Target weight (kg)',userValue('weight_kg',line.target_weight_kg??line.weight_kg),'number')}${programInput('target_max_rpe','Maximum RPE (0–10)',line.target_max_rpe,'number')}${programInput('rest_sec','Rest (seconds)',line.rest_sec??line.rest_seconds,'number')}</div><details><summary>Muscles & exercise note</summary><div class="form-grid">${programInput('primary_muscle','Primary muscle',line.primary_muscle)}${programInput('secondary_muscles','Secondary muscles (comma separated)',Array.isArray(secondary)?secondary.join(', '):secondary)}${programInput('note','Exercise note',line.note)}</div></details>`;E('programLines').append(row);refreshProgramOrder();}
function refreshProgramOrder(){const rows=[...E('programLines').children];E('programEmpty').hidden=rows.length>0;rows.forEach((row,i)=>{row.querySelector('.line-number').textContent=String(i+1).padStart(2,'0');row.querySelector('[data-line-action="up"]').disabled=i===0;row.querySelector('[data-line-action="down"]').disabled=i===rows.length-1;});}
function restoreProgramLines(lines=[]){E('programLines').replaceChildren();for(const line of lines)addProgramLine(line);refreshProgramOrder();}
function programLines(){return [...E('programLines').children].map(row=>{const out={...row.originalLine};for(const input of row.querySelectorAll('[data-line-field]')){const key=input.dataset.lineField;if(input.type==='number'){if(input.value===''){delete out[key];continue;}const value=Number(input.value);if(!Number.isFinite(value)||value<0)throw Error('Exercise targets must be non-negative numbers.');if(key==='target_max_rpe'&&value>10)throw Error('Maximum RPE must be between 0 and 10.');if(key==='target_sets'&&!Number.isInteger(value))throw Error('Sets must be a whole number.');out[key]=key==='target_weight_kg'?canonicalValues({weight_kg:value}).weight_kg:value;}else out[key]=key==='secondary_muscles'?input.value.split(',').map(v=>v.trim()).filter(Boolean):input.value.trim();}if(out.target_reps_low!==undefined)delete out.target_reps;if(!out.exercise)throw Error('Name each exercise, or remove its empty row.');return out;});}
E('addProgramLine').onclick=()=>{addProgramLine();E('programLines').lastElementChild.querySelector('input').focus();};
E('programLines').onclick=ev=>{const button=ev.target.closest('[data-line-action]');if(!button)return;const row=button.closest('.program-line'),action=button.dataset.lineAction;if(action==='remove')row.remove();else if(action==='up'&&row.previousElementSibling)row.previousElementSibling.before(row);else if(action==='down'&&row.nextElementSibling)row.nextElementSibling.after(row);refreshProgramOrder();};
