function feedbackReadout(f){if(!f)return '';if(f.band)return `<div class="bio-readout"><span>LIVE HR BAND</span><strong>${human(f.band.floor_bpm)}–${human(f.band.ceiling_bpm)} <small>bpm</small></strong><p>${f.status==='stale'?'Readings are stale · coaching paused':f.status==='warmup'?'Warm-up · cues stay silent':f.position==='inBand'?'In your band · on track':f.position==='above'?'Above your band':'Below your band'}${f.smoothed_bpm!=null?' · '+human(f.smoothed_bpm)+' bpm observed':''}</p><details><summary>Guidance decision & coverage</summary>${summary(f)}</details></div>`;if(f.target_bpm!=null||f.stop)return `<div class="bio-readout"><span>BELOW-HR METRONOME</span><strong>${f.target_bpm!=null?human(f.target_bpm)+' <small>bpm tempo</small>':'Session ended'}</strong><p>${esc(f.stop_reason||'Following fresh smoothed HR')} · ${f.interval_ms!=null?human(f.interval_ms)+' ms interval':'No pulse scheduled'}</p></div>`;return `<details><summary>Live feedback</summary>${summary(f)}</details>`;}
function resonanceReadout(r){if(!r)return '';return `<div class="bio-readout"><span>RESONANCE SWEEP RESULT</span><strong>${human(r.locked_bpm)} <small>breaths/min</small></strong><p>${r.did_lock?'Best recorded response in this sweep':'No lock · coherence fallback'} · ${esc(r.reason||'Session-specific RR estimate')}</p>${chart((r.scores||[]).map(s=>({x:s.bpm+' br/min',y:s.rsa_amplitude})),'Observed HR swing per breath (bpm)')}<details><summary>Per-pace beats, cycles & RMSSD</summary>${summary(r)}</details></div>`;}
