function populateTimingPlan(v){const f=E('circadianPlanForm');if(!f)return;f.elements.plan_sleep.value=v.habitual_sleep_hour>=0?minuteTime(Math.round(v.habitual_sleep_hour*60)%1440):'';f.elements.plan_wake.value=v.habitual_wake_hour>=0?minuteTime(Math.round(v.habitual_wake_hour*60)%1440):'';f.elements.circadian_shift_hours.value=v.circadian_shift_hours||0;}
function timingPlanReadout(p){const clock=v=>minuteTime(Math.round(v*60)%1440);if(!p?.days?.length)return help(p?.direction==='none'?'No timing shift requested. Your usual sleep and wake schedule is retained.':'Configure your current sleep/wake schedule and intended shift below to view timing targets.');return `<div class="table-scroll"><table><caption>Configured timing targets · ${esc(p.direction==='advance'?'Move earlier':'Move later')} over ${p.estimated_days} days</caption><thead><tr><th scope="col">Day</th><th scope="col">Bed / wake</th><th scope="col">Bright light window</th><th scope="col">Dim from</th></tr></thead><tbody>${p.days.map(d=>`<tr><th scope="row">${d.day_index}</th><td>${clock(d.target_sleep_hour)} / ${clock(d.target_wake_hour)}</td><td>${clock(d.bright_light_start_hour)}–${clock(d.bright_light_end_hour)}</td><td>${clock(d.dim_from_hour)}</td></tr>`).join('')}</tbody></table></div>`;}

