async function registry(){const v=await api('/api/devices');E('deviceRegistry').innerHTML=v.devices?.length?v.devices.map(d=>`<div class="saved-record"><div><strong>${esc(d.name)}</strong><small>${esc(d.address)} · ${d.active?'Active strap':'Saved strap'}</small></div><div class="record-actions"><button data-registry="switch" data-address="${esc(d.address)}" data-name="${esc(d.name)}">${d.active?'Reconnect':'Use strap'}</button><button data-registry="forget" data-address="${esc(d.address)}">Forget</button><button data-registry="delete-data" data-address="${esc(d.address)}">Delete data</button></div></div>`).join(''):help('Scan nearby straps to save your first device.');}
async function storageInfo(){const v=await api('/api/storage');E('storageInspect').innerHTML=`<p class="stat">${((v.reclaimable_bytes||0)/1048576).toFixed(2)}<small>MB diagnostics reclaimable</small></p><details><summary>Files, records & cleanup targets</summary>${summary(v)}</details>`;}
async function fusionInfo(){const v=await api('/api/fusion?date='+day);E('sourceFusion').innerHTML=fusionReadout(v);const sources=Object.keys(v.imported_sources||{});E('sourceActions').innerHTML=sources.map(s=>`<button data-source-delete="${esc(s)}">Delete ${esc(sourceName(s))} records</button>`).join('')||help('No imported daily-score sources for this day. Strap originals remain separate.');}
async function spot(action='status',seconds){const v=await api('/api/hrv',{action,...(seconds?{duration_seconds:Number(seconds)}:{})});spotActive=!!v.active;E('spotResult').innerHTML=v.active?`<div class="capture-progress"><progress max="${v.duration_seconds}" value="${v.elapsed_seconds||0}" aria-label="Stillness capture progress"></progress><strong>${Math.floor(v.elapsed_seconds||0)} / ${v.duration_seconds}s</strong><span>${v.rr_count||0} RR intervals received</span></div>${summary(v.result)}`:summary(v);}
async function fullInsights(){const v=await api('/api/insights?days='+E('trendRange').value+'&date='+day);E('intelligence').innerHTML=readinessReadout(lastInsightsReadiness)+weeklyReadout(v);E('fullInsights').innerHTML=circadianReadout(v.circadian)+comparisonReadout(v.comparisons)+doseReadout(v.behaviour?.dose_response)+`<details><summary>Complete analysis, coverage & technical evidence</summary>${summary(v)}</details>`;E('behaviour').innerHTML=associationReadout(v.effects?.length?v.effects:v.behavior_effects||v.behaviour?.same_day_effects,v.behaviour);E('effects').innerHTML=experimentReadout(v.experiments);E('activityHeatmap').innerHTML=activityHeatmap(v.calendar||v.streaks?.calendar);}
async function sourceCompare(){const get=n=>document.querySelector(`[name="${n}"]`).value;const source=get('seriesSource'),days=get('seriesDays')||30,through=get('seriesThrough')||day;E('sourceComparison').innerHTML=help('Loading source-attributed observations…');const metrics=[get('compareA'),get('compareB')];const series=await Promise.all(metrics.map(m=>api('/api/metric-series?metric='+encodeURIComponent(m)+'&days='+days+'&date='+through+'&source='+encodeURIComponent(source))));E('comparison').replaceChildren();E('sourceComparison').innerHTML=series.map(v=>`<h3>${esc(label(v.metric))}</h3>${Object.entries(Object.groupBy?Object.groupBy(v.points||[],p=>p.source):groupSource(v.points||[])).map(([s,points])=>chart(points.map(p=>({x:p.date,y:displayedMetric(v.metric,p.value)})),label(v.metric)+' · '+sourceName(s))).join('')}${help(esc(v.missing||'No observations from the selected source.'))}`).join('');}
function routeDetail(r){const pts=(r.points||[]).map(p=>({lat:Number(p.lat??p.LatitudeDegrees),lon:Number(p.lon??p.LongitudeDegrees)})).filter(p=>Number.isFinite(p.lat)&&Number.isFinite(p.lon));if(!pts.length)throw Error('This record has no valid route coordinates.');const lats=pts.map(p=>p.lat),lons=pts.map(p=>p.lon),loLat=Math.min(...lats),hiLat=Math.max(...lats),loLon=Math.min(...lons),hiLon=Math.max(...lons);let view=E('routeDetail');if(!view){view=document.createElement('div');view.id='routeDetail';E('routes').append(view);}view.innerHTML=card(esc(r.name||'Route'),`<svg class="route-map" viewBox="0 0 700 330" role="img" aria-label="Recorded GPS route, north at top"><path d="${pts.map((p,i)=>(i?'L':'M')+(35+(p.lon-loLon)/(hiLon-loLon||1)*630).toFixed(1)+' '+(295-(p.lat-loLat)/(hiLat-loLat||1)*260).toFixed(1)).join(' ')}" fill="none" stroke="currentColor" stroke-width="3"/><text x="665" y="25">N ↑</text></svg>${help(pts.length+' recorded coordinates · local route outline · '+esc(sourceName(r.source||'imported')))}${summary({name:r.name,distance:typeof r.distance_km==='number'?human(userValue('distance_km',r.distance_km))+' '+(preferences.distance_units==='imperial'?'mi':'km'):undefined,source:r.source})}`);view.scrollIntoView({behavior:'smooth',block:'center'});}
function groupSource(points){const groups={};for(const p of points)(groups[p.source]??=[]).push(p);return groups;}
