document.addEventListener('click',async ev=>{const b=ev.target.closest('button');if(!b)return;try{if(b.dataset.registry){const action=b.dataset.registry;if(['forget','delete-data'].includes(action)&&!await boopConfirm({title:action==='forget'?'Forget this strap?':'Delete original strap recordings?',message:action==='forget'?'Remove this strap from the registry. Its recordings are kept.':'Delete this strap’s original local recordings. A recovery snapshot will be saved.',confirmLabel:action==='forget'?'Forget strap':'Delete recordings',destructive:true,trigger:b}))return;await api('/api/devices',{action,address:b.dataset.address,name:b.dataset.name,confirm:true});await registry();}if(b.id==='registryScan'){b.disabled=true;E('registryChoices').innerHTML=help('Scanning nearby BOOP straps…');const v=await api('/api/scan',{});E('registryChoices').innerHTML=v.devices?.length?v.devices.map(d=>`<button data-registry="register" data-address="${esc(d.address)}" data-name="${esc(d.name)}">Add ${esc(d.name)}</button>`).join(''):help('No strap found. Put your BOOP strap in pairing mode and keep it nearby.');}if(b.id==='inspectStorage')await storageInfo();if(b.id==='cleanStorage'){if(!await boopConfirm({title:'Clean up diagnostic files?',message:'Reclaim only the optional diagnostic files listed above. Original health records remain saved.',confirmLabel:'Clean up diagnostics',trigger:b}))return;E('storageInspect').innerHTML=summary(await api('/api/storage',{action:'cleanup',confirm:true}));}if(b.dataset.sourceDelete){if(!await boopConfirm({title:'Delete imported source records?',message:'Delete all imported records attributed to '+sourceName(b.dataset.sourceDelete)+'? Strap originals remain saved.',confirmLabel:'Delete imported records',destructive:true,trigger:b}))return;await api('/api/sources',{action:'delete',source:b.dataset.sourceDelete,confirm:true});await fusionInfo();await loadDay();}if(b.dataset.route){const r=records.route.find(x=>x.id===b.dataset.route);routeDetail(r);}if(b.id==='spotStatus')await spot();if(b.id==='spotStop')await spot('stop');}catch(e){fail(e);}finally{if(b.id==='registryScan')b.disabled=false;}});
setInterval(()=>{if(spotActive)spot().catch(fail);},2000);let sessionPolling=false;setInterval(async()=>{if(sessionPolling||(!timer.active&&!['tools','activity'].includes(active)))return;sessionPolling=true;try{await loadSession();}catch(e){fail(e);}finally{sessionPolling=false;}},1000);
function navigate(){const previous=active,p=location.hash.slice(1)||'today';active=pages.includes(p)?p:'today';document.querySelectorAll('.page').forEach(e=>e.hidden=e.id!==active);document.querySelectorAll('[data-page]').forEach(e=>{e.classList.toggle('selected',e.dataset.page===active);e.setAttribute('aria-current',e.dataset.page===active?'page':'false');});if(previous!==active){const destination=active;window.scrollTo({top:0,left:0,behavior:'instant'});requestAnimationFrame(()=>{if(active!==destination)return;window.scrollTo({top:0,left:0,behavior:'instant'});const heading=E(active)?.querySelector('h1');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}const nav=E('navigation'),link=nav?.querySelector('[aria-current="page"]');if(nav&&link&&nav.scrollWidth>nav.clientWidth){const left=link.offsetLeft-nav.offsetLeft;if(left<nav.scrollLeft)nav.scrollLeft=left-8;else if(left+link.offsetWidth>nav.scrollLeft+nav.clientWidth)nav.scrollLeft=left+link.offsetWidth-nav.clientWidth+8;}});}loadVisible().catch(fail);}
